int blkgen_build(void) {
    block *root = gui_root_block();
    root->w = 800; root->h = 600;
    gui_commit_desc(blkgen_descs, sizeof(blkgen_descs) / sizeof(blkgen_descs[0]));
    for (uint32_t i = 0; i < sizeof(blkgen_descs) /
                     sizeof(blkgen_descs[0]); i++)
        gui_mark_dirty(blkgen_descs[i].id);
    gui_mark_dirty(root->id);
    layout_run();

    uint32_t cap = btable_capacity();
    for (uint32_t id = 1; id <= cap; id++) {
        block *b = btable_get(id);
        if (!b) continue;
        ser_write("BLKGEN id="); blkgen_put_dec(b->id);
        ser_write(" x="); blkgen_put_dec(b->x);
        ser_write(" y="); blkgen_put_dec(b->y);
        ser_write(" w="); blkgen_put_dec(b->w);
        ser_write(" h="); blkgen_put_dec(b->h);
        ser_write("\n");
    }
    return 0;
}
